#!/usr/bin/env node
/* Regenerates lib/assets.js from the source files and, with --binaries,
   compiles standalone executables with Bun into ./bin-dist. */
"use strict";
const fs = require("fs"), path = require("path"), { execFileSync } = require("child_process");
const lib = path.join(__dirname, "lib");
const read = (f) => fs.readFileSync(path.join(lib, f), "utf8");
const version = require("./package.json").version;
fs.writeFileSync(path.join(lib, "assets.js"),
  "/* Generated by build.js. Do not edit. */\n" +
  "module.exports = " + JSON.stringify({ version, runtime: read("runtime.js"), icons: read("icons.json"), licenses: read("ICON-LICENSES.txt") }) + ";\n");
console.log("wrote lib/assets.js");
if (process.argv.includes("--binaries")) {
  const bun = process.env.BUN || "bun";
  const targets = [
    ["bun-linux-x64", "sprigc-linux-x64"],
    ["bun-linux-arm64", "sprigc-linux-arm64"],
    ["bun-darwin-arm64", "sprigc-macos-arm64"],
    ["bun-darwin-x64", "sprigc-macos-x64"],
    ["bun-windows-x64", "sprigc-windows-x64.exe"]
  ];
  fs.mkdirSync(path.join(__dirname, "bin-dist"), { recursive: true });
  for (const [target, name] of targets) {
    if (process.argv.includes("--host") && target !== "bun-linux-x64") continue;
    execFileSync(bun, ["build", "bin/sprigc.js", "--compile", "--minify", "--target=" + target, "--outfile", "bin-dist/" + name], { stdio: "inherit", cwd: __dirname });
  }
}
